  1→import { useState, useRef, useEffect } from 'react';
  2→import { useTranslation } from '../hooks/useTranslation';
  3→import { useAgent } from '../hooks/useAgent';
  4→import { SlashCommandMenu } from './SlashCommandMenu';
  5→import { fetchSkills } from '../services/skillsService';
  6→import type { SkillInfo } from '../types';
  7→import './ChatInput.css';
  8→
  9→interface ChatInputProps {
 10→  pendingSkillCommand?: string | null;
 11→  onSkillCommandConsumed?: () => void;
 12→}
 13→
 14→export function ChatInput({ pendingSkillCommand, onSkillCommandConsumed }: ChatInputProps) {
 15→  const { t } = useTranslation();
 16→  const { sendMessage, isStreaming } = useAgent();
 17→  const [text, setText] = useState('');
 18→  const textareaRef = useRef<HTMLTextAreaElement>(null);
 19→
 20→  const [skills, setSkills] = useState<SkillInfo[]>([]);
 21→  const [showSlashMenu, setShowSlashMenu] = useState(false);
 22→  const [slashFilter, setSlashFilter] = useState('');
 23→
 24→  // Load skills on mount and refresh when toggled/updated
 25→  useEffect(() => {
 26→    fetchSkills().then(setSkills).catch(() => {});
 27→    const handler = () => { fetchSkills().then(setSkills).catch(() => {}); };
 28→    window.addEventListener('skills-updated', handler);
 29→    return () => window.removeEventListener('skills-updated', handler);
 30→  }, []);
 31→
 32→  // Consume pending skill command from sidebar "Use" button
 33→  useEffect(() => {
 34→    if (pendingSkillCommand) {
 35→      setText(prev => {
 36→        const trimmed = prev.trim();
 37→        const command = `${t('useSkillPlaceholder')} /${pendingSkillCommand}`;
 38→        return trimmed ? `${trimmed} ${command}` : command;
 39→      });
 40→      onSkillCommandConsumed?.();
 41→      textareaRef.current?.focus();
 42→    }
 43→  }, [pendingSkillCommand, onSkillCommandConsumed]);
 44→
 45→  const handleSend = () => {
 46→    const trimmed = text.trim();
 47→    if (!trimmed || isStreaming) return;
 48→    sendMessage(trimmed);
 49→    setText('');
 50→    setShowSlashMenu(false);
 51→    if (textareaRef.current) {
 52→      textareaRef.current.style.height = 'auto';
 53→    }
 54→  };
 55→
 56→  const handleKeyDown = (e: React.KeyboardEvent) => {
 57→    // When slash menu is open, let it handle arrow keys and Enter
 58→    if (showSlashMenu) {
 59→      if (['ArrowDown', 'ArrowUp', 'Enter', 'Escape'].includes(e.key)) {
 60→        return; // SlashCommandMenu handles these via document listener
 61→      }
 62→    }
 63→
 64→    if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
 65→      e.preventDefault();
 66→      handleSend();
 67→    }
 68→  };
 69→
 70→  const slashStartRef = useRef<number>(-1);
 71→
 72→  const handleInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
 73→    const val = e.target.value;
 74→    const cursorPos = e.target.selectionStart;
 75→    setText(val);
 76→
 77→    // Find the slash token at or before the cursor
 78→    const beforeCursor = val.slice(0, cursorPos);
 79→    const slashIdx = beforeCursor.lastIndexOf('/');
 80→    if (slashIdx !== -1) {
 81→      const token = beforeCursor.slice(slashIdx + 1);
 82→      // Valid slash command: no spaces in the token
 83→      if (!token.includes(' ')) {
 84→        slashStartRef.current = slashIdx;
 85→        setShowSlashMenu(true);
 86→        setSlashFilter(token);
 87→      } else {
 88→        setShowSlashMenu(false);
 89→      }
 90→    } else {
 91→      setShowSlashMenu(false);
 92→    }
 93→
 94→    const el = e.target;
 95→    el.style.height = 'auto';
 96→    el.style.height = Math.min(el.scrollHeight, 150) + 'px';
 97→  };
 98→
 99→  const handleSlashSelect = (skillName: string) => {
100→    const start = slashStartRef.current;
101→    const cursorPos = textareaRef.current?.selectionStart ?? text.length;
102→    const before = text.slice(0, start);
103→    const after = text.slice(cursorPos);
104→    setText(`${before}/${skillName} ${after}`);
105→    setShowSlashMenu(false);
106→    slashStartRef.current = -1;
107→    // Set cursor after the inserted command
108→    const newCursorPos = start + skillName.length + 2; // "/" + name + " "
109→    requestAnimationFrame(() => {
110→      textareaRef.current?.focus();
111→      textareaRef.current?.setSelectionRange(newCursorPos, newCursorPos);
112→    });
113→  };
114→
115→  return (
116→    <div className="chat-input">
117→      <div className="chat-input__textarea-wrapper">
118→        {showSlashMenu && skills.length > 0 && (
119→          <SlashCommandMenu
120→            skills={skills}
121→            filter={slashFilter}
122→            onSelect={handleSlashSelect}
123→            onClose={() => setShowSlashMenu(false)}
124→          />
125→        )}
126→        <textarea
127→          ref={textareaRef}
128→          className="chat-input__textarea"
129→          value={text}
130→          onChange={handleInput}
131→          onKeyDown={handleKeyDown}
132→          placeholder={isStreaming ? '' : t('chatPlaceholder')}
133→          disabled={isStreaming}
134→          rows={1}
135→        />
136→        {isStreaming && (
137→          <span className="chat-input__shimmer">{t('chatPlaceholderWaiting')}</span>
138→        )}
139→      </div>
140→      <button
141→        className="chat-input__send"
142→        onClick={handleSend}
143→        disabled={isStreaming || !text.trim()}
144→      >
145→        {t('send')}
146→      </button>
147→    </div>
148→  );
149→}
