import express, { Request, Response } from "express";
import { query, AgentDefinition, SettingSource, HookCallbackMatcher } from "@anthropic-ai/claude-agent-sdk";
import { Langfuse } from "langfuse";
import { mkdirSync, writeFileSync, existsSync, readdirSync, readFileSync, symlinkSync } from "fs";
import { homedir } from "os";
import { join } from "path";
import type { QueryRequest, HealthResponse, AgentDefinitionPayload } from "./types.js";

// Claude CLI requires certain directories/files under ~/.claude to exist.
// The container uses a tmpfs mount at ~/.claude which starts empty, so we
// create the expected structure at startup.
const claudeDir = join(homedir(), ".claude");
for (const sub of ["debug", "projects"]) {
  const dir = join(claudeDir, sub);
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
}
const settingsFile = join(claudeDir, "remote-settings.json");
if (!existsSync(settingsFile)) {
  writeFileSync(settingsFile, "{}");
}

const SKILLS_DIR = join(process.cwd(), "skills");

// Skills are volume-mounted at /app/skills/ but the CLI's Skill tool
// discovers skills from ~/.claude/skills/ (user-level). Symlink so the
// CLI subprocess can find and invoke them.
const userSkillsDir = join(claudeDir, "skills");
if (existsSync(SKILLS_DIR) && !existsSync(userSkillsDir)) {
  try {
    symlinkSync(SKILLS_DIR, userSkillsDir);
    console.log(`[sidecar] Symlinked ${userSkillsDir} -> ${SKILLS_DIR}`);
  } catch (e) {
    console.error(`[sidecar] Failed to symlink skills: ${e}`);
  }
}

